    }
    if (ch === '(') {
      i++;
      push('lparen', start, i);
      continue;
    }
    if (ch === ')') {
      i++;
      push('rparen', start, i);
      continue;
    }
    if (ch === '[') {
      i++;
      push('lbrack', start, i);
      continue;
    }
    if (ch === ']') {
      i++;
      push('rbrack', start, i);
      continue;
    }
    if (ch === ',') {
      i++;
      push('comma', start, i);
      continue;
    }
    // Unknown character (take a whole code point).
    const cp = source.codePointAt(i)!;
    const len = cp > 0xffff ? 2 : 1;
    i += len;
    fail(`Nieznany znak „${source.slice(start, i)}”. Tego znaku nie ma w języku Logo.`, start, i);
  }

  const eof: Token = {
    kind: 'eof',
    text: '',
    value: 0,
    name: '',
    line,
    col: n - lineOffset + 1,
    offset: n,
    end: n,
    spaceBefore: true,
    spaceAfter: true,
    lineStart: true,
    lineEnd: true,
  };
  const last = tokens[tokens.length - 1];
  if (last) {
    last.spaceAfter = true;
    last.lineEnd = true;
  }
  tokens.push(eof);
  return { tokens, comments };
}

export function fmtInt(n: number): string {
  return n.toLocaleString('pl-PL').replace(/ /g, ' ');
}

