 * animate or step. Errors are thrown as LogoRuntimeError and leave `segments` intact.
 */
export class Machine {
  segments: Segment[] = [];
  ops = 0;
  frames = 0;
  pos: Vec3 = [0, 0, 0];
  penDown = true;
  color = DEFAULT_COLOR;
  width = DEFAULT_WIDTH;
  globals = new Map<string, number>();
