    this.toVectors();
    const c = cosDeg(a);
    const s = sinDeg(a);
    const U = combine(this.U, c, this.R, s);
    const R = combine(this.R, c, this.U, -s);
    this.U = U;
    this.R = R;
    this.orthonormalize();
