const PREFIX = 'logomocja.v1.';

/** localStorage with JSON values; silently degrades when storage is blocked or full. */
export const store = {
  get<T>(key: string, fallback: T): T {
    try {
      const raw = localStorage.getItem(PREFIX + key);
