  setPartial(p: { seg: Segment; t: number } | null): void {
    this.partial = p;
    this.request();
  }

  setTurtle(t: TurtleState | null): void {
    this.turtle = t;
    this.request();
  }

  setOverlay(o: Overlay | null): void {
