      const k = Math.min((now - t0) / dur, 1);
      const e = 1 - Math.pow(1 - k, 3);
      this.scale = Math.exp(Math.log(from.s) + (Math.log(s) - Math.log(from.s)) * e);
      this.cx = from.x + (tx - from.x) * e;
      this.cy = from.y + (ty - from.y) * e;
