    const [x0, y0] = this.toScreen(b.minX, b.maxY);
    const [x1, y1] = this.toScreen(b.maxX, b.minY);
    return x0 >= 0 && y0 >= 0 && x1 <= this.w && y1 <= this.h;
  }

