      const { seg, t } = this.partial;
      const to: [number, number, number] = [
        seg.from[0] + (seg.to[0] - seg.from[0]) * t,
        seg.from[1] + (seg.to[1] - seg.from[1]) * t,
        seg.from[2] + (seg.to[2] - seg.from[2]) * t,
      ];
      drawSegments(ctx, [{ ...seg, to }], this.toScreen, 1);
    }
