  }

  private loop = (now: number): void => {
    if (this.state !== 'running' || !this.session) return;
    const dt = Math.min(now - this.lastTime, 100) / 1000;
    this.lastTime = now;
    const rate = RATES[this.speed]!;
    const s = this.session;
    if (rate <= TWEEN_MAX) {
