{
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', (e) => errs.push(e.message));
  page.on('requestfailed', (r) => errs.push('reqfail ' + r.url()));
  page.on('response', (r) => r.status() >= 400 && errs.push(`${r.status()} ${r.url()}`));
  await page.goto('http://localhost:4174/Logomocja/builds/x/#/zadania/kwiat', { waitUntil: 'networkidle' });
  await page.reload({ waitUntil: 'networkidle' });
  check('subpath: task route survives refresh', (await page.textContent('.task-title')) === 'Kwiat z kwadratów');
  const r = await page.evaluate(() => window.logomocja.open('gora 90 np 50', '3d'));
  check('subpath: 3D chunk loads and draws', r.segments.length === 1 && !r.error, JSON.stringify(r.error));
  check('subpath: no failed requests', errs.length === 0, errs.join('; '));
  await ctx.close();
}

const base = 'http://localhost:4173/';
// 2. drafts per mode survive reload; backup + restore
{
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  await page.goto(base + '#/', { waitUntil: 'networkidle' });
  await page.click('.cm-content');
  await page.keyboard.press('Control+a');
  await page.keyboard.type('np 77 ; moj szkic 2D');
  await page.click('[data-mode="3d"]');
  await page.waitForTimeout(300);
  await page.click('.cm-content');
  await page.keyboard.press('Control+a');
  await page.keyboard.type('gora 45 np 33 ; szkic 3D');
  await page.waitForTimeout(500);
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  const t3 = await page.evaluate(() => document.querySelector('.cm-content').textContent);
  check('3D draft survives reload and mode is remembered', t3.includes('szkic 3D'), t3);
  await page.click('[data-mode="2d"]');
  await page.waitForTimeout(200);
  const t2 = await page.evaluate(() => document.querySelector('.cm-content').textContent);
  check('2D draft survives reload', t2.includes('moj szkic 2D'), t2);
  // load example over the draft → toast with restore
  await page.goto(base + '#/przyklady/gwiazda');
  await page.waitForTimeout(400);
  const toastText = await page.textContent('.toast');
  check('loading an example keeps the draft (toast)', /odłożono/.test(toastText ?? ''), toastText);
  await page.click('.toast .btn-quiet');
  await page.waitForTimeout(300);
  const back = await page.evaluate(() => document.querySelector('.cm-content').textContent);
  check('restore brings the draft back', back.includes('moj szkic 2D'), back);
  // undo after example load via Ctrl+Z also works
  await page.goto(base + '#/przyklady/kwadrat');
  await page.waitForTimeout(300);
  await page.click('.cm-content');
  await page.keyboard.press('Control+z');
  await page.waitForTimeout(200);
  const undone = await page.evaluate(() => document.querySelector('.cm-content').textContent);
  check('Ctrl+Z after loading undoes the replacement', undone.includes('moj szkic 2D'), undone.slice(0, 60));
  await ctx.close();
}

// 3. permalink round trip
{
